package com.estoqueinteligente.report;
import java.math.BigDecimal;import java.time.LocalDate;import com.estoqueinteligente.product.*;
public class StockReportResponse{private final Long id;private final String name,categoryName;private final Integer quantity,minimumStock;private final BigDecimal costPrice,salePrice,stockValue;private final LocalDate expirationDate;private final ProductStatus status;public StockReportResponse(ProductResponse p){id=p.getId();name=p.getName();categoryName=p.getCategoryName();quantity=p.getQuantity();minimumStock=p.getMinimumStock();costPrice=p.getCostPrice();salePrice=p.getSalePrice();expirationDate=p.getExpirationDate();status=p.getStatus();stockValue=costPrice.multiply(BigDecimal.valueOf(quantity));}public Long getId(){return id;}public String getName(){return name;}public String getCategoryName(){return categoryName;}public Integer getQuantity(){return quantity;}public Integer getMinimumStock(){return minimumStock;}public BigDecimal getCostPrice(){return costPrice;}public BigDecimal getSalePrice(){return salePrice;}public LocalDate getExpirationDate(){return expirationDate;}public ProductStatus getStatus(){return status;}public BigDecimal getStockValue(){return stockValue;}}
